CREATE OR ALTER PROCEDURE [dbo].[uspIntegrationLog_GetAll] (
	@SearchText NVARCHAR(MAX) = NULL
	, @IntegrationChannelId UNIQUEIDENTIFIER = NULL
	, @LogStatus NVARCHAR(MAX) = NULL
	, @Page INT = 1
	, @PageSize INT = 10
	, @SortField NVARCHAR(100) = NULL
	, @SortOrder NVARCHAR(20) = NULL)
AS
BEGIN
	SET NOCOUNT ON;
	IF @Page IS NULL OR @Page < 1 SET @Page = 1;
	IF @PageSize IS NULL OR @PageSize < 1 SET @PageSize = 10;
	IF @PageSize > 1000 SET @PageSize = 1000;

	;WITH TempResult AS
	(
		SELECT
			t.[Id]
			, t.[IntegrationChannelId]
			, t.[DirectionCode]
			, t.[OperationCode]
			, t.[CorrelationId]
			, t.[IdempotencyKey]
			, t.[RequestAt]
			, t.[ResponseAt]
			, t.[HttpStatus]
			, t.[LogStatus]
			, t.[ErrorCode]
			, t.[ErrorMessage]
			, t.[PayloadHash]
			, t.[CreatedDate]
		FROM [dbo].[IntegrationLog] AS t
		
		WHERE (ISNULL(@SearchText, '') = '' OR t.[DirectionCode] LIKE CONCAT('%', @SearchText, '%') OR t.[OperationCode] LIKE CONCAT('%', @SearchText, '%') OR t.[ErrorCode] LIKE CONCAT('%', @SearchText, '%'))
			AND (@IntegrationChannelId IS NULL OR t.[IntegrationChannelId] = @IntegrationChannelId)
			AND (ISNULL(@LogStatus, '') = '' OR t.[LogStatus] = @LogStatus)
			AND t.IsDeleted = 0
	),
	TempCount (TotalRow) AS (SELECT COUNT(*) FROM TempResult)
	SELECT r.*, c.TotalRow
	FROM TempResult AS r CROSS JOIN TempCount AS c
	ORDER BY
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'integrationChannelId' THEN r.[IntegrationChannelId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'integrationChannelId' THEN r.[IntegrationChannelId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'directionCode' THEN r.[DirectionCode] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'directionCode' THEN r.[DirectionCode] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'operationCode' THEN r.[OperationCode] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'operationCode' THEN r.[OperationCode] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'correlationId' THEN r.[CorrelationId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'correlationId' THEN r.[CorrelationId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'idempotencyKey' THEN r.[IdempotencyKey] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'idempotencyKey' THEN r.[IdempotencyKey] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'requestAt' THEN r.[RequestAt] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'requestAt' THEN r.[RequestAt] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'responseAt' THEN r.[ResponseAt] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'responseAt' THEN r.[ResponseAt] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'httpStatus' THEN r.[HttpStatus] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'httpStatus' THEN r.[HttpStatus] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'logStatus' THEN r.[LogStatus] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'logStatus' THEN r.[LogStatus] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'errorCode' THEN r.[ErrorCode] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'errorCode' THEN r.[ErrorCode] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'errorMessage' THEN r.[ErrorMessage] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'errorMessage' THEN r.[ErrorMessage] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'payloadHash' THEN r.[PayloadHash] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'payloadHash' THEN r.[PayloadHash] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END DESC,
		r.[CreatedDate] DESC
	OFFSET (@PageSize * (@Page - 1)) ROWS FETCH NEXT @PageSize ROWS ONLY
	OPTION (RECOMPILE);
END
GO
